            if current not in visited:
                visited.add(current)
                for neighbor, weight in graph.get(current, []):
                    tentative_distance = current_distance + weight
                    if tentative_distance < distances[neighbor]:
                        distances[neighbor] = tentative_distance
                        heapq.heappush(queue, (tentative_distance, neighbor))
        return float('inf'), None

    # Let's try BFS and DFS first
    bfs_path = bfs(graph, source, target)
    dfs_path = dfs(graph, source, target)

    # If either BFS or DFS finds a path, we return the result
    for path in [bfs_path, dfs_path]:
        if path:
            return (distances[target], path)

    # If BFS and DFS fail, let's try Dijkstra's algorithm
    dijkstra_path = dijkstra(graph, source, target)
    if dijkstra_path[0] != float('inf'):
        return dijkstra_path

    # If all methods fail, return infinity and None
